const langs = ($input.first().json.languages) || [];
const EXCLUDE_ISO = ['en', 'pst', 'ps', 'cus', 'pt_old'];
const targets = langs.filter(l => !EXCLUDE_ISO.includes(l.lang_iso));
if (targets.length === 0) throw new Error('No target languages resolved');
return [{ json: { targetLangIds: targets.map(l => l.lang_id).join(','), targetCount: targets.length } }];

const scope = $('Build Scope').first().json;
const untrTotal = parseInt(($('Count Untranslated').first().json.headers || {})['x-pagination-total-count'] || '0', 10);
const allTotal = parseInt(($('Count All Keys').first().json.headers || {})['x-pagination-total-count'] || '0', 10);
if (!untrTotal || !allTotal) throw new Error('Missing pagination totals');
const BASE = 'https://api.lokalise.com/api2/projects/964775386a3ce03ecca883.03770715/keys';
const LIMIT = 500;
const out = [];
for (let p = 1; p <= Math.ceil(untrTotal / LIMIT); p++) {
  out.push({ json: { url: BASE + '?limit=' + LIMIT + '&page=' + p + '&filter_untranslated=1&filter_translation_lang_ids=' + scope.targetLangIds } });
}
for (let p = 1; p <= Math.ceil(allTotal / LIMIT); p++) {
  out.push({ json: { url: BASE + '?limit=' + LIMIT + '&page=' + p + '&include_translations=1&filter_translation_lang_ids=640' } });
}
return out;

// Strip Figma / screenshot meta-commentary from key descriptions. Tags untouched.
const untranslatedIds = new Set();
const meta = new Map();
for (const it of $input.all()) {
  const b = it.json || {};
  if (Array.isArray(b.screenshots)) continue;
  const keys = b.keys || [];
  if (!Array.isArray(keys) || keys.length === 0) continue;
  const isPassB = Array.isArray(keys[0].translations);
  for (const k of keys) {
    if (isPassB) meta.set(k.key_id, { key_id: k.key_id, key_name: (k.key_name && (k.key_name.web || k.key_name.other)) || '', description: k.description || '' });
    else untranslatedIds.add(k.key_id);
  }
}

function clean(d) {
  let s = String(d);
  s = s.replace(/\s*No screen in the current Figma file shows this string\.?\s*$/i, '');
  s = s.replace(/\s*Screenshot:\s[^]*$/i, '');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

const proposals = [];
const rollback = [];
let changed = 0, unchanged = 0, wouldEmpty = 0, stillMentionsFigma = 0;

for (const id of untranslatedIds) {
  const m = meta.get(id);
  if (!m) continue;
  const before = m.description;
  const after = clean(before);
  if (after === before) { unchanged++; continue; }
  if (!after) { wouldEmpty++; continue; }            // never blank a description
  if (/figma/i.test(after)) stillMentionsFigma++;
  changed++;
  proposals.push({ key_id: m.key_id, key_name: m.key_name, new_description: after });
  rollback.push({ i: m.key_id, removed: before.slice(after.length) });
}

return [{ json: {
  scopeSize: untranslatedIds.size,
  toChange: changed,
  unchanged: unchanged,
  skippedBecauseWouldBeEmpty: wouldEmpty,
  stillMentionsFigmaAfterClean: stillMentionsFigma,
  sample: proposals.slice(0, 5),
  rollbackSample: rollback.slice(0, 5),
  proposals: proposals
} }];

const TEST_LIMIT = 0;   // 0 = full run

const all = ($input.first().json.proposals) || [];
if (!Array.isArray(all) || all.length === 0) throw new Error('No proposals to write');
const p = TEST_LIMIT > 0 ? all.slice(0, TEST_LIMIT) : all;

const SIZE = 100;
const out = [];
for (let i = 0; i < p.length; i += SIZE) {
  const slice = p.slice(i, i + SIZE);
  out.push({ json: {
    batch: Math.floor(i / SIZE) + 1,
    size: slice.length,
    body: { keys: slice.map(x => ({ key_id: x.key_id, description: x.new_description })) }
  } });
}
return out;

let updated = 0;
const errors = [];
for (const it of $input.all()) {
  const b = it.json || {};
  if (Array.isArray(b.keys)) updated += b.keys.length;
  if (b.errors && b.errors.length) { for (const e of b.errors) errors.push(e); }
}
return [{ json: { keysUpdated: updated, errorCount: errors.length, errors: errors.slice(0, 20) } }];

const j = $input.first().json;
const leaves = {};
for (const p of (j.proposals || [])) {
  if (p.key_name.startsWith('report::') && !p.key_name.startsWith('report::classic::')) continue;
  const parts = p.key_name.split('::');
  const leaf = parts[parts.length - 1];
  const fam = parts.slice(0, 2).join('::');
  const k = fam + ' | ' + leaf;
  leaves[k] = (leaves[k] || 0) + 1;
}
const rows = Object.keys(leaves).sort();
return [{ json: {
  proposedCount: j.proposedCount,
  unmatchedCount: j.unmatchedCount,
  genericFallbackCount: j.genericFallbackCount,
  tagDistribution: j.tagDistribution,
  designedCount: j.designedCount,
  sourceOnlyCount: j.sourceOnlyCount,
  emptySourceKeys: j.emptySourceKeys,
  distinctLeafCount: rows.length,
  leafInventory: rows.join('\n')
} }];
